package br.com.gestaoservicos.convite.controller;
import br.com.gestaoservicos.convite.dto.*; import br.com.gestaoservicos.convite.service.ConviteUnidadeService; import br.com.gestaoservicos.security.ContextoUnidade; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/v1") public class ConviteUnidadeController {private final ConviteUnidadeService servico;public ConviteUnidadeController(ConviteUnidadeService s){servico=s;} private UUID unidade(){return ContextoUnidade.atual().map(ContextoUnidade.Selecao::unidadeId).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Selecione uma unidade pelo cabeçalho X-Unidade-Id"));}
 @GetMapping("/unidades/atual/convites") @PreAuthorize("@autorizacaoUnidade.possuiAlgumPerfil('ADMIN')") List<ConviteUnidadeResponseDTO> listar(){return servico.listar(unidade());}
 @PostMapping("/unidades/atual/convites") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("@autorizacaoUnidade.possuiAlgumPerfil('ADMIN')") ConviteUnidadeResponseDTO criar(@Valid @RequestBody CriarConviteUnidadeRequestDTO r){return servico.criar(unidade(),r.email(),r.perfil());}
 @DeleteMapping("/unidades/atual/convites/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("@autorizacaoUnidade.possuiAlgumPerfil('ADMIN')") void revogar(@PathVariable UUID id){servico.revogar(unidade(),id);}
 @PostMapping("/convites/aceitar") @ResponseStatus(HttpStatus.NO_CONTENT) void aceitar(@Valid @RequestBody AceitarConviteRequestDTO r,Authentication a){servico.aceitar(UUID.fromString(a.getName()),r.codigo());}}
